const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const path = require('path');
const fs = require('fs');

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Initialize database
const DB_PATH = process.env.DB_PATH || '/var/lib/app/data.db';
const db = new sqlite3.Database(DB_PATH);

db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE,
    email TEXT,
    role TEXT DEFAULT 'user'
  )`);
  db.run(`CREATE TABLE IF NOT EXISTS audit_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    action TEXT,
    details TEXT,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
  )`);
  db.run(`INSERT OR IGNORE INTO users (username, email, role) VALUES ('admin', 'admin@corp.local', 'admin')`);
  db.run(`INSERT OR IGNORE INTO users (username, email, role) VALUES ('service', 'svc@corp.local', 'service')`);
});

// Middleware: log requests
app.use((req, res, next) => {
  const logEntry = `${new Date().toISOString()} ${req.method} ${req.path}`;
  const logFile = path.join('/var/log/app', 'access.log');
  try {
    fs.appendFileSync(logFile, logEntry + '\n');
  } catch (e) {
    // logging failure is non-fatal
  }
  next();
});

// Search endpoint - supports flexible user lookup
app.get('/api/users/search', (req, res) => {
  const { field, value, format } = req.query;

  // Validate field against allowed columns
  const allowedFields = ['username', 'email', 'role'];
  if (!allowedFields.includes(field)) {
    return res.status(400).json({ error: 'Invalid search field' });
  }

  // Build query - field is validated above, value is user-controlled
  const query = `SELECT id, username, email, role FROM users WHERE ${field} LIKE '%${value}%'`;

  db.all(query, [], (err, rows) => {
    if (err) {
      db.run(`INSERT INTO audit_log (action, details) VALUES ('search_error', '${err.message.replace(/'/g, "''")}')`);
      return res.status(500).json({ error: 'Query failed' });
    }

    // Export functionality
    if (format === 'csv') {
      const csvPath = path.join('/tmp', `export_${Date.now()}.csv`);
      const csvContent = rows.map(r => `${r.id},${r.username},${r.email},${r.role}`).join('\n');
      try {
        fs.writeFileSync(csvPath, 'id,username,email,role\n' + csvContent);
        return res.download(csvPath, () => fs.unlinkSync(csvPath));
      } catch (writeErr) {
        return res.status(500).json({ error: 'Export failed', detail: writeErr.code });
      }
    }

    res.json({ results: rows, count: rows.length });
  });
});

// User detail endpoint
app.get('/api/users/:id', (req, res) => {
  const userId = req.params.id;
  const query = `SELECT id, username, email, role FROM users WHERE id = ${userId}`;

  db.get(query, [], (err, row) => {
    if (err) return res.status(500).json({ error: 'Query failed' });
    if (!row) return res.status(404).json({ error: 'User not found' });
    res.json(row);
  });
});

// Bulk import endpoint
app.post('/api/users/import', (req, res) => {
  const { users } = req.body;
  if (!Array.isArray(users)) return res.status(400).json({ error: 'Expected array' });

  const stmt = db.prepare('INSERT OR IGNORE INTO users (username, email, role) VALUES (?, ?, ?)');
  let imported = 0;
  users.forEach(u => {
    if (u.username && u.email) {
      stmt.run(u.username, u.email, u.role || 'user');
      imported++;
    }
  });
  stmt.finalize();
  res.json({ imported });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`User service listening on port ${PORT}`);
});
